CREATE TABLE IF NOT EXISTS schema_migrations (name TEXT PRIMARY KEY, applied_at TIMESTAMPTZ NOT NULL DEFAULT NOW());
CREATE TABLE IF NOT EXISTS users (id BIGSERIAL PRIMARY KEY, name TEXT NOT NULL, username TEXT NOT NULL UNIQUE, password_hash TEXT NOT NULL, role TEXT NOT NULL CHECK (role IN ('ADMIN','MANAGER','CASHIER','KITCHEN')), active BOOLEAN NOT NULL DEFAULT TRUE, created_at TIMESTAMPTZ NOT NULL DEFAULT NOW());
CREATE TABLE IF NOT EXISTS sessions (token_hash TEXT PRIMARY KEY, user_id BIGINT NOT NULL REFERENCES users(id) ON DELETE CASCADE, expires_at TIMESTAMPTZ NOT NULL, created_at TIMESTAMPTZ NOT NULL DEFAULT NOW());
CREATE INDEX IF NOT EXISTS sessions_user_idx ON sessions(user_id);
CREATE INDEX IF NOT EXISTS sessions_expires_idx ON sessions(expires_at);
CREATE TABLE IF NOT EXISTS bar_tables (id BIGSERIAL PRIMARY KEY, number INTEGER NOT NULL UNIQUE, label TEXT, active BOOLEAN NOT NULL DEFAULT TRUE);
CREATE TABLE IF NOT EXISTS products (id BIGSERIAL PRIMARY KEY, name TEXT NOT NULL, category TEXT NOT NULL, price_cents INTEGER NOT NULL CHECK (price_cents >= 0), stock_quantity INTEGER NOT NULL DEFAULT 0, min_stock INTEGER NOT NULL DEFAULT 0, destination TEXT NOT NULL DEFAULT 'DIRECT' CHECK (destination IN ('KITCHEN','BAR','DIRECT')), active BOOLEAN NOT NULL DEFAULT TRUE, created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(), updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW());
CREATE INDEX IF NOT EXISTS products_category_idx ON products(category);
CREATE TABLE IF NOT EXISTS cash_sessions (id BIGSERIAL PRIMARY KEY, opened_by BIGINT NOT NULL REFERENCES users(id), opening_amount_cents INTEGER NOT NULL DEFAULT 0, opened_at TIMESTAMPTZ NOT NULL DEFAULT NOW(), closed_by BIGINT REFERENCES users(id), closed_at TIMESTAMPTZ, closing_amount_cents INTEGER, expected_amount_cents INTEGER, notes TEXT, status TEXT NOT NULL DEFAULT 'OPEN' CHECK (status IN ('OPEN','CLOSED')));
CREATE UNIQUE INDEX IF NOT EXISTS cash_one_open_idx ON cash_sessions(status) WHERE status = 'OPEN';
CREATE TABLE IF NOT EXISTS commands (id BIGSERIAL PRIMARY KEY, command_number INTEGER NOT NULL, table_id BIGINT NOT NULL REFERENCES bar_tables(id), customer_name TEXT, status TEXT NOT NULL DEFAULT 'OPEN' CHECK (status IN ('OPEN','CLOSED','CANCELLED')), opened_by BIGINT NOT NULL REFERENCES users(id), opened_at TIMESTAMPTZ NOT NULL DEFAULT NOW(), closed_at TIMESTAMPTZ, notes TEXT);
CREATE UNIQUE INDEX IF NOT EXISTS commands_open_number_idx ON commands(command_number) WHERE status = 'OPEN';
CREATE INDEX IF NOT EXISTS commands_status_idx ON commands(status);
CREATE TABLE IF NOT EXISTS order_items (id BIGSERIAL PRIMARY KEY, command_id BIGINT NOT NULL REFERENCES commands(id), product_id BIGINT NOT NULL REFERENCES products(id), product_name TEXT NOT NULL, unit_price_cents INTEGER NOT NULL, quantity INTEGER NOT NULL CHECK (quantity > 0), destination TEXT NOT NULL CHECK (destination IN ('KITCHEN','BAR','DIRECT')), status TEXT NOT NULL DEFAULT 'PENDING' CHECK (status IN ('PENDING','SENT','PREPARING','READY','DELIVERED','CANCELLED')), added_by BIGINT NOT NULL REFERENCES users(id), created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(), sent_at TIMESTAMPTZ, cancelled_at TIMESTAMPTZ);
CREATE INDEX IF NOT EXISTS order_items_command_idx ON order_items(command_id);
CREATE INDEX IF NOT EXISTS order_items_status_idx ON order_items(status);
CREATE TABLE IF NOT EXISTS kitchen_tickets (id BIGSERIAL PRIMARY KEY, command_id BIGINT NOT NULL REFERENCES commands(id), created_by BIGINT NOT NULL REFERENCES users(id), created_at TIMESTAMPTZ NOT NULL DEFAULT NOW());
CREATE TABLE IF NOT EXISTS kitchen_ticket_items (ticket_id BIGINT NOT NULL REFERENCES kitchen_tickets(id) ON DELETE CASCADE, order_item_id BIGINT NOT NULL REFERENCES order_items(id), PRIMARY KEY (ticket_id,order_item_id));
CREATE TABLE IF NOT EXISTS stock_movements (id BIGSERIAL PRIMARY KEY, product_id BIGINT NOT NULL REFERENCES products(id), quantity INTEGER NOT NULL, reason TEXT NOT NULL, order_item_id BIGINT REFERENCES order_items(id), user_id BIGINT NOT NULL REFERENCES users(id), created_at TIMESTAMPTZ NOT NULL DEFAULT NOW());
CREATE INDEX IF NOT EXISTS stock_movements_product_idx ON stock_movements(product_id);
CREATE TABLE IF NOT EXISTS sales (id BIGSERIAL PRIMARY KEY, command_id BIGINT NOT NULL UNIQUE REFERENCES commands(id), cash_session_id BIGINT NOT NULL REFERENCES cash_sessions(id), subtotal_cents INTEGER NOT NULL, discount_cents INTEGER NOT NULL DEFAULT 0, service_fee_cents INTEGER NOT NULL DEFAULT 0, total_cents INTEGER NOT NULL, status TEXT NOT NULL DEFAULT 'COMPLETED' CHECK (status IN ('COMPLETED','CANCELLED')), created_by BIGINT NOT NULL REFERENCES users(id), created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(), cancelled_by BIGINT REFERENCES users(id), cancelled_at TIMESTAMPTZ, cancellation_reason TEXT);
CREATE TABLE IF NOT EXISTS payments (id BIGSERIAL PRIMARY KEY, sale_id BIGINT NOT NULL REFERENCES sales(id) ON DELETE CASCADE, method TEXT NOT NULL CHECK (method IN ('CASH','PIX','DEBIT','CREDIT')), amount_cents INTEGER NOT NULL CHECK (amount_cents > 0), received_cents INTEGER, change_cents INTEGER NOT NULL DEFAULT 0);
CREATE INDEX IF NOT EXISTS payments_sale_idx ON payments(sale_id);
INSERT INTO bar_tables (number,label) SELECT n,'Mesa ' || n FROM generate_series(1,12) AS n ON CONFLICT (number) DO NOTHING;
